export const HEADER_BRAND_HTML = "<a href=\"/ambre/\" class=\"site-logo\" aria-label=\"Décode ton esprit, Ambre\">\n  <span class=\"site-logo-mark\"><picture><source srcset=\"/images/logo-mark-128.webp\" type=\"image/webp\"><img src=\"/images/logo-mark-128.png\" alt=\"\" width=\"64\" height=\"64\"></picture></span>\n  <span class=\"site-wordmark\">Décode ton esprit</span>\n</a>\n<button type=\"button\" class=\"site-menu-toggle\" id=\"site-menu-toggle\" aria-expanded=\"false\" aria-controls=\"site-navigation\" aria-label=\"Navigation principale\">\n  <svg width=\"18\" height=\"18\" viewBox=\"0 0 20 20\" fill=\"none\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M3 5h14M3 10h14M3 15h14\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>\n</button>";
export const SITE_SYSTEM_CSS = "/* Décode ton esprit — système commun (« carnet clinique »).\n   Source unique : chargée par le site (layouts/partials/head.html) et recopiée\n   dans l'espace personnel par scripts/build_navigation.mjs. Jetons, en-tête,\n   pied de page, titres, boutons, champs, fenêtres : rien de cela ne se redéfinit ailleurs. */\n:root {\n  --ink: #172D3C;\n  --muted: #526575;\n  --bg: #F2F5F7;\n  --surface: #FFFFFF;\n  --line: #D6E0E6;\n  --line-strong: #748693;\n  --accent: #205E54;\n  --accent-wash: #E8F2EF;\n  --danger: #962B40;\n  --font-title: Georgia, \"Times New Roman\", serif;\n  --font-ui: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --t-xs: 13px; --t-sm: 14px; --t-md: 16px; --t-lg: 18px; --t-xl: 22px; --t-2xl: 28px; --t-3xl: 36px;\n  --s1: 4px; --s2: 8px; --s3: 12px; --s4: 16px; --s5: 24px; --s6: 32px; --s7: 48px; --s8: 64px;\n  --r-control: 6px; --r-card: 10px;\n  --page: 720px;\n  --page-wide: 1040px;\n  --gutter: 16px;\n  --header-height: 56px;\n}\n@media (min-width: 600px) { :root { --gutter: 24px; --header-height: 64px; } }\n\n*, *::before, *::after { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n/* A tap only navigates: no tinted flash, and the focus ring is reserved for the keyboard (:focus-visible). */\nhtml { -webkit-text-size-adjust: 100%; -webkit-tap-highlight-color: transparent; }\nbody {\n  display: flex;\n  flex-direction: column;\n  min-height: 100dvh;\n  margin: 0;\n  background: var(--bg);\n  color: var(--ink);\n  font: 400 var(--t-md)/1.6 var(--font-ui);\n  -webkit-font-smoothing: antialiased;\n}\n[hidden] { display: none !important; }\nimg { max-width: 100%; height: auto; }\n:where(h1, h2, h3, h4, p) { margin: 0 0 var(--s3); }\n:where(h1) {\n  margin-bottom: var(--s5);\n  font: 400 clamp(var(--t-2xl), 4vw, var(--t-3xl))/1.15 var(--font-title);\n  letter-spacing: -.01em;\n  overflow-wrap: anywhere;\n}\n:where(h2) { font: 600 clamp(var(--t-lg), 2.2vw, 20px)/1.3 var(--font-ui); }\n:where(h3, h4) { font: 600 var(--t-md)/1.35 var(--font-ui); }\n:where(a) { color: var(--accent); text-underline-offset: 3px; }\n:where(summary) { cursor: pointer; }\n:where(fieldset) { min-width: 0; margin: 0; padding: 0; border: 0; }\n:where(a, button, summary, input, textarea, select, [tabindex]):focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n/* Headings and regions that receive focus by script (tabindex=\"-1\") never draw a ring. */\n:where([tabindex=\"-1\"]):focus { outline: none; }\n\n/* Page frame: the header, the content and the footer share one left edge. */\n.header-inner, .footer-inner, #main-content, .shell {\n  width: 100%;\n  max-width: calc(var(--page-wide) + 2 * var(--gutter));\n  margin-inline: auto;\n  padding-inline: var(--gutter);\n}\n#main-content, .shell { flex: 1; padding-block: var(--s5) var(--s7); }\n@media (min-width: 600px) { #main-content, .shell { padding-block: var(--s7) var(--s8); } }\n:where(#main-content, .shell) :target { scroll-margin-top: calc(var(--header-height) + var(--s4)); }\n\n/* Header */\n.site-header { position: sticky; top: 0; z-index: 100; background: var(--surface); border-bottom: 1px solid var(--line); }\n.header-inner { display: flex; align-items: center; justify-content: space-between; gap: var(--s4); min-height: var(--header-height); }\n.site-header .site-logo {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--s2);\n  min-height: 44px;\n  color: var(--ink);\n  font: 700 var(--t-lg)/1.25 var(--font-title);\n  text-decoration: none;\n  white-space: nowrap;\n}\n.site-logo-mark { display: flex; align-items: center; justify-content: center; flex: none; width: 36px; height: 36px; overflow: hidden; }\n.site-logo-mark img { display: block; flex: none; width: 64px; height: 64px; max-width: none; }\n/* The header shows the eye only, never the site name (owner's decision); the name stays for screen readers. */\n.site-header .site-wordmark { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }\n.site-header .site-menu-toggle {\n  display: none;\n  flex: none;\n  width: 44px;\n  height: 44px;\n  padding: 0;\n  align-items: center;\n  justify-content: center;\n  border: 1px solid var(--line);\n  border-radius: 9px;\n  background: var(--surface);\n  color: var(--ink);\n}\n@media (hover: hover) { .site-header .site-menu-toggle:hover { background: var(--accent-wash); } }\n.site-header .nav-links { display: flex; align-items: center; gap: var(--s1); margin: 0; padding: 0; list-style: none; }\n.site-header .nav-links li { margin: 0; }\n.site-header .nav-links a {\n  display: flex;\n  align-items: center;\n  min-height: 44px;\n  padding: 0 10px;\n  border-radius: var(--r-control);\n  color: var(--muted);\n  font: 500 var(--t-sm)/1.3 var(--font-ui);\n  text-decoration: none;\n  white-space: nowrap;\n}\n@media (hover: hover) { .site-header .nav-links a:hover { color: var(--ink); background: var(--accent-wash); } }\n.site-header .nav-links a[aria-current=\"page\"] { color: var(--ink); font-weight: 600; box-shadow: inset 0 -2px 0 var(--accent); border-radius: 0; }\n.site-header .nav-links a:active, .site-header .site-menu-toggle:active, .site-logo:active { background: var(--accent-wash); }\n/* Phone: the eye centred, the menu button on the right (as before the redesign). */\n@media (max-width: 640px) {\n  .header-inner { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); }\n  .site-header .site-logo { grid-column: 2; grid-row: 1; min-width: 44px; justify-content: center; }\n  .site-header .site-menu-toggle { grid-column: 3; grid-row: 1; justify-self: end; }\n}\n@media (max-width: 1099px) {\n  .site-header .site-menu-toggle { display: inline-flex; }\n  .site-navigation {\n    position: absolute;\n    inset: 100% 0 auto;\n    max-height: calc(100dvh - var(--header-height));\n    padding: var(--s2) var(--gutter) var(--s4);\n    overflow: auto;\n    background: var(--surface);\n    border-bottom: 1px solid var(--line);\n  }\n  .site-navigation:not(.is-open) { display: none; }\n  .site-header .nav-links { flex-direction: column; align-items: stretch; gap: 0; }\n  .site-header .nav-links a { min-height: 48px; padding: 0 var(--s3); font-size: var(--t-md); border-radius: 0; }\n  .site-header .nav-links a[aria-current=\"page\"] { box-shadow: inset 2px 0 0 var(--accent); }\n}\n\n/* A page that takes time to prepare: a thin bar under the header (set by the personal space while it waits). */\nhtml.is-navigating .site-header::after { content: ''; position: absolute; left: 0; bottom: -1px; width: 0; height: 2px; background: var(--accent); animation: navigating 1.2s ease-in-out infinite; }\nhtml.is-navigating, html.is-navigating * { cursor: progress; }\n@keyframes navigating { 0% { left: 0; width: 0; } 50% { left: 0; width: 100%; } 100% { left: 100%; width: 0; } }\n@media (prefers-reduced-motion: reduce) { html.is-navigating .site-header::after { width: 100%; opacity: .5; } }\n\n/* Footer: the site name (to Ambre) only, below a hairline that closes the page. */\n.site-footer { flex: none; padding-block: var(--s4); border-top: 1px solid var(--line); }\n.footer-minimal { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0 var(--s5); }\n.site-footer :where(.site-logo, .footer-link) { display: inline-flex; align-items: center; min-height: 44px; color: var(--muted); font: 400 var(--t-sm)/1.45 var(--font-ui); text-decoration: none; }\n.site-footer :where(.site-logo, .footer-link):hover { text-decoration: underline; }\n\n/* Buttons: primary by default, then secondary, text, and red for deletion only. */\n:where(button, .button) {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--s2);\n  min-height: 44px;\n  margin: 0;\n  padding: 0 18px;\n  border: 1px solid var(--accent);\n  border-radius: var(--r-control);\n  background: var(--accent);\n  color: #fff;\n  font: 600 var(--t-md)/1.2 var(--font-ui);\n  text-align: center;\n  text-decoration: none;\n  cursor: pointer;\n  transition: background-color .12s, color .12s, border-color .12s;\n}\n@media (hover: hover) { :where(button, .button):hover { background: color-mix(in srgb, var(--accent) 86%, #000); } }\n:where(button, .button):disabled { opacity: .55; cursor: not-allowed; }\n/* Pressed: an immediate, quiet answer to a tap or a click (no tinted browser flash). */\n:where(button, .button):not(:disabled):active { transform: scale(.98); }\n:where(button, .button):where(:not(.secondary, .carto-btn, .carto-fb, .text, .text-link, .carto-btn-quiet, .carto-see, .carto-note-add, .carto-detail, .carto-scope-link, .carto-ambre-remove, .close, .carto-dialog-close, .danger)):not(:disabled):active { background: color-mix(in srgb, var(--accent) 80%, #000); }\n:where(button, .button):where(.secondary, .carto-btn, .carto-fb, .close, .carto-dialog-close):not(:disabled):active { background: var(--accent-wash); }\n:where(button, .button, a):where(.text, .text-link, .carto-btn-quiet, .carto-see, .carto-note-add, .carto-detail, .carto-scope-link, .carto-ambre-remove):active { opacity: .65; transform: none; }\n@media (prefers-reduced-motion: no-preference) { :where(button, .button) { transition: background-color .12s, color .12s, border-color .12s, transform .08s, opacity .12s; } }\n:where(button, .button):where(.secondary, .carto-btn, .carto-fb) { border-color: var(--line-strong); background: var(--surface); color: var(--ink); }\n@media (hover: hover) { :where(button, .button):where(.secondary, .carto-btn, .carto-fb):hover { background: var(--accent-wash); } }\n:where(button, .button, a):where(.text, .text-link, .carto-btn-quiet, .carto-see, .carto-note-add, .carto-detail, .carto-scope-link, .carto-ambre-remove) {\n  display: inline-flex;\n  align-items: center;\n  min-height: 44px;\n  padding: 0;\n  border: 0;\n  border-radius: var(--r-control);\n  background: none;\n  color: var(--accent);\n  font: 600 var(--t-md)/1.2 var(--font-ui);\n  text-decoration: none;\n  cursor: pointer;\n}\n:where(button, .button, a):where(.text, .text-link, .carto-btn-quiet, .carto-see, .carto-note-add, .carto-detail, .carto-scope-link, .carto-ambre-remove):hover { background: none; text-decoration: underline; }\n:where(button, .button):where(.carto-btn-primary) { border-color: var(--accent); background: var(--accent); color: #fff; }\n@media (hover: hover) { :where(button, .button):where(.carto-btn-primary):hover { background: color-mix(in srgb, var(--accent) 86%, #000); } }\n:where(button, .button).danger { border-color: var(--danger); background: var(--danger); color: #fff; }\n@media (hover: hover) { :where(button, .button).danger:hover { background: color-mix(in srgb, var(--danger) 86%, #000); } }\n:where(button, .button, a).danger:where(.text, .text-link) { border-color: transparent; background: none; color: var(--danger); }\n:where(button, .button, a).danger:where(.text, .text-link):hover { background: none; }\n\n/* Fields: one shape. */\n:where(label, legend) { display: block; margin: 0 0 6px; padding: 0; font: 600 var(--t-sm)/1.45 var(--font-ui); }\n:where(input:not([type=checkbox], [type=radio]), select, textarea) {\n  display: block;\n  width: 100%;\n  min-height: 48px;\n  margin: 0;\n  padding: 0 var(--s3);\n  border: 1px solid var(--line-strong);\n  border-radius: var(--r-control);\n  background: var(--surface);\n  color: var(--ink);\n  font: 400 var(--t-md)/1.5 var(--font-ui);\n}\n:where(textarea) { min-height: 112px; padding: var(--s3); resize: vertical; }\n:where(input[type=checkbox], input[type=radio]) { flex: none; width: 20px; height: 20px; margin: 2px 0 0; accent-color: var(--accent); }\n:where(input, textarea)::placeholder { color: var(--muted); opacity: 1; }\n:where(input, select, textarea)[aria-invalid=\"true\"] { border-color: var(--danger); }\n\n/* One window: centred on a computer, a bottom sheet on a phone. */\n:where(dialog) {\n  width: min(520px, calc(100% - 2 * var(--gutter)));\n  max-width: none;\n  max-height: 88dvh;\n  margin: auto;\n  padding: var(--s5);\n  border: 0;\n  border-radius: var(--r-card);\n  background: var(--surface);\n  color: var(--ink);\n  box-shadow: 0 8px 24px rgb(23 45 60 / .12);\n  overflow: auto;\n  overscroll-behavior: contain;\n}\ndialog::backdrop { background: rgb(23 45 60 / .45); }\ndialog[open] { animation: window-in .16s ease-out; }\n@keyframes window-in { from { opacity: 0; } }\n:where(.dialog-top, .carto-dialog-head) { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s4); }\n:where(dialog) :where(h2) { margin: 0 0 var(--s4); padding-top: 9px; font: 600 20px/1.3 var(--font-ui); letter-spacing: 0; }\n:where(button):where(.close, .carto-dialog-close) {\n  flex: none;\n  width: 44px;\n  min-height: 44px;\n  margin: 0 -10px 0 0;\n  padding: 0;\n  border-color: transparent;\n  background: none;\n  color: var(--ink);\n  font: 400 24px/1 var(--font-ui);\n}\n@media (hover: hover) { :where(button):where(.close, .carto-dialog-close):hover { background: var(--accent-wash); } }\n:where(dialog) :where(.actions, .carto-note-actions) { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--s3); margin-top: var(--s5); }\n@media (max-width: 599px) {\n  :where(dialog) {\n    width: 100%;\n    margin: auto 0 0;\n    padding: var(--s4) var(--gutter) max(var(--s4), env(safe-area-inset-bottom));\n    border-radius: var(--r-card) var(--r-card) 0 0;\n  }\n  :where(dialog) :where(.actions, .carto-note-actions) > :where(button, .button) { flex: 1 1 0; }\n}\n\n.visually-hidden, .skip-link:not(:focus) {\n  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;\n}\n.skip-link:focus { position: fixed; top: var(--s2); left: var(--s2); z-index: 120; padding: var(--s2) var(--s3); border-radius: var(--r-control); background: var(--ink); color: #fff; }\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; }\n}\n@media print {\n  .site-header, .site-footer, .skip-link { display: none !important; }\n  body { background: #fff; }\n}\n";
export const SITE_FOOTER_HTML = "<footer class=\"site-footer\">\n  <div class=\"footer-inner footer-minimal\">\n    <a href=\"/ambre/\" class=\"site-logo\">Décode ton esprit</a>\n  </div>\n</footer>";
export const SITE_NAVIGATION_SCRIPT = "(function () {\n  'use strict';\n  // Safari applies :active to a touched link or button only when a touch listener exists: the pressed\n  // state of cards and buttons then answers the finger at once (passive, no effect on scrolling).\n  document.addEventListener('touchstart', function () {}, { passive: true });\n  var toggle = document.getElementById('site-menu-toggle');\n  var navigation = document.getElementById('site-navigation');\n  if (!toggle || !navigation) return;\n  function close() { navigation.classList.remove('is-open'); toggle.setAttribute('aria-expanded', 'false'); }\n  toggle.addEventListener('click', function () {\n    var open = toggle.getAttribute('aria-expanded') !== 'true';\n    navigation.classList.toggle('is-open', open);\n    toggle.setAttribute('aria-expanded', String(open));\n  });\n  navigation.addEventListener('click', function (event) { if (event.target.closest('a,button')) close(); });\n  document.addEventListener('click', function (event) { if (!event.target.closest('.site-header')) close(); });\n  document.addEventListener('keydown', function (event) {\n    if (event.key !== 'Escape' || toggle.getAttribute('aria-expanded') !== 'true') return;\n    close();\n    toggle.focus();\n    event.preventDefault();\n  });\n  var breakpoint = window.matchMedia('(max-width: 1099px)');\n  if (breakpoint.addEventListener) breakpoint.addEventListener('change', close);\n  else if (breakpoint.addListener) breakpoint.addListener(close);\n})();\n";
